     1→// 🦎 Mini Zig Compiler - Phase 2.1: Tokenizer
     2→// src/tokenizer.zig: 소스코드 → Token 스트림
     3→
     4→const std = @import("std");
     5→
     6→pub const Location = struct {
     7→    line: usize,
     8→    column: usize,
     9→    start: usize,
    10→    end: usize,
    11→};
    12→
    13→pub const Token = struct {
    14→    tag: Tag,
    15→    loc: Location,
    16→
    17→    pub const Tag = enum {
    18→        // Keywords
    19→        fn_,
    20→        const_,
    21→        var_,
    22→        if_,
    23→        else_,
    24→        while_,
    25→        for_,
    26→        return_,
    27→        struct_,
    28→        enum_,
    29→        union_,
    30→        error_,
    31→        try_,
    32→        catch_,
    33→        pub_,
    34→        inline_,
    35→        comptime_,
    36→
    37→        // Literals
    38→        integer,
    39→        float,
    40→        string,
    41→        char_literal,
    42→        true_,
    43→        false_,
    44→        null_,
    45→
    46→        // Identifiers & types
    47→        identifier,
    48→
    49→        // Operators
    50→        plus,          // +
    51→        minus,         // -
    52→        star,          // *
    53→        slash,         // /
    54→        percent,       // %
    55→        equal,         // =
    56→        equal_equal,   // ==
    57→        bang,          // !
    58→        bang_equal,    // !=
    59→        less,          // <
    60→        less_equal,    // <=
    61→        greater,       // >
    62→        greater_equal, // >=
    63→        ampersand,     // &
    64→        pipe,          // |
    65→        caret,         // ^
    66→        tilde,         // ~
    67→        lshift,        // <<
    68→        rshift,        // >>
    69→        and_,          // and
    70→        or_,           // or
    71→        not_,          // not
    72→        dot,           // .
    73→        dot_dot,       // ..
    74→        arrow,         // =>
    75→        question,      // ?
    76→        colon,         // :
    77→        double_colon,  // ::
    78→
    79→        // Delimiters
    80→        lparen,        // (
    81→        rparen,        // )
    82→        lbrace,        // {
    83→        rbrace,        // }
    84→        lbracket,      // [
    85→        rbracket,      // ]
    86→        semicolon,     // ;
    87→        comma,         // ,
    88→
    89→        // Special
    90→        eof,
    91→        invalid,
    92→    };
    93→
    94→    pub fn lexeme(self: Token, source: []const u8) []const u8 {
    95→        return source[self.loc.start..self.loc.end];
    96→    }
    97→};
    98→
    99→pub const Tokenizer = struct {
   100→    source: []const u8,
   101→    pos: usize,
   102→    line: usize,
   103→    column: usize,
   104→    line_start: usize,
   105→
   106→    pub fn init(source: []const u8) Tokenizer {
   107→        return .{
   108→            .source = source,
   109→            .pos = 0,
   110→            .line = 1,
   111→            .column = 1,
   112→            .line_start = 0,
   113→        };
   114→    }
   115→
   116→    pub fn nextToken(self: *Tokenizer) Token {
   117→        // Skip whitespace and comments
   118→        while (self.pos < self.source.len) {
   119→            const c = self.source[self.pos];
   120→
   121→            if (isWhitespace(c)) {
   122→                if (c == '\n') {
   123→                    self.line += 1;
   124→                    self.line_start = self.pos + 1;
   125→                    self.column = 1;
   126→                } else {
   127→                    self.column += 1;
   128→                }
   129→                self.pos += 1;
   130→                continue;
   131→            }
   132→
   133→            // Line comment
   134→            if (c == '/' and self.peek() == '/') {
   135→                while (self.pos < self.source.len and self.source[self.pos] != '\n') {
   136→                    self.pos += 1;
   137→                }
   138→                continue;
   139→            }
   140→
   141→            // Block comment
   142→            if (c == '/' and self.peek() == '*') {
   143→                self.pos += 2;
   144→                self.column += 2;
   145→                while (self.pos < self.source.len - 1) {
   146→                    if (self.source[self.pos] == '*' and self.source[self.pos + 1] == '/') {
   147→                        self.pos += 2;
   148→                        self.column += 2;
   149→                        break;
   150→                    }
   151→                    if (self.source[self.pos] == '\n') {
   152→                        self.line += 1;
   153→                        self.line_start = self.pos + 1;
   154→                        self.column = 1;
   155→                    } else {
   156→                        self.column += 1;
   157→                    }
   158→                    self.pos += 1;
   159→                }
   160→                continue;
   161→            }
   162→
   163→            break;
   164→        }
   165→
   166→        if (self.pos >= self.source.len) {
   167→            return Token{
   168→                .tag = .eof,
   169→                .loc = .{
   170→                    .line = self.line,
   171→                    .column = self.column,
   172→                    .start = self.pos,
   173→                    .end = self.pos,
   174→                },
   175→            };
   176→        }
   177→
   178→        const start = self.pos;
   179→        const start_column = self.column;
   180→        const c = self.source[self.pos];
   181→
   182→        // Number literal
   183→        if (isDigit(c)) {
   184→            return self.scanNumber(start, start_column);
   185→        }
   186→
   187→        // String literal
   188→        if (c == '"') {
   189→            return self.scanString(start, start_column);
   190→        }
   191→
   192→        // Character literal
   193→        if (c == '\'') {
   194→            return self.scanCharLiteral(start, start_column);
   195→        }
   196→
   197→        // Identifier or keyword
   198→        if (isIdentifierStart(c)) {
   199→            return self.scanIdentifier(start, start_column);
   200→        }
   201→
   202→        // Operators and delimiters
   203→        return self.scanOperator(start, start_column);
   204→    }
   205→
   206→    fn scanNumber(self: *Tokenizer, start: usize, start_column: usize) Token {
   207→        while (self.pos < self.source.len and isDigit(self.source[self.pos])) {
   208→            self.pos += 1;
   209→            self.column += 1;
   210→        }
   211→
   212→        // Float
   213→        if (self.pos < self.source.len and self.source[self.pos] == '.') {
   214→            self.pos += 1;
   215→            self.column += 1;
   216→
   217→            while (self.pos < self.source.len and isDigit(self.source[self.pos])) {
   218→                self.pos += 1;
   219→                self.column += 1;
   220→            }
   221→
   222→            return Token{
   223→                .tag = .float,
   224→                .loc = .{ .line = self.line, .column = start_column, .start = start, .end = self.pos },
   225→            };
   226→        }
   227→
   228→        return Token{
   229→            .tag = .integer,
   230→            .loc = .{ .line = self.line, .column = start_column, .start = start, .end = self.pos },
   231→        };
   232→    }
   233→
   234→    fn scanString(self: *Tokenizer, start: usize, start_column: usize) Token {
   235→        self.pos += 1; // Skip opening "
   236→        self.column += 1;
   237→
   238→        while (self.pos < self.source.len and self.source[self.pos] != '"') {
   239→            if (self.source[self.pos] == '\\') {
   240→                self.pos += 2;
   241→                self.column += 2;
   242→            } else if (self.source[self.pos] == '\n') {
   243→                self.line += 1;
   244→                self.line_start = self.pos + 1;
   245→                self.column = 1;
   246→                self.pos += 1;
   247→            } else {
   248→                self.pos += 1;
   249→                self.column += 1;
   250→            }
   251→        }
   252→
   253→        if (self.pos < self.source.len) {
   254→            self.pos += 1; // Skip closing "
   255→            self.column += 1;
   256→        }
   257→
   258→        return Token{
   259→            .tag = .string,
   260→            .loc = .{ .line = self.line, .column = start_column, .start = start, .end = self.pos },
   261→        };
   262→    }
   263→
   264→    fn scanCharLiteral(self: *Tokenizer, start: usize, start_column: usize) Token {
   265→        self.pos += 1;
   266→        self.column += 1;
   267→
   268→        if (self.source[self.pos] == '\\') {
   269→            self.pos += 2;
   270→            self.column += 2;
   271→        } else {
   272→            self.pos += 1;
   273→            self.column += 1;
   274→        }
   275→
   276→        if (self.pos < self.source.len and self.source[self.pos] == '\'') {
   277→            self.pos += 1;
   278→            self.column += 1;
   279→        }
   280→
   281→        return Token{
   282→            .tag = .char_literal,
   283→            .loc = .{ .line = self.line, .column = start_column, .start = start, .end = self.pos },
   284→        };
   285→    }
   286→
   287→    fn scanIdentifier(self: *Tokenizer, start: usize, start_column: usize) Token {
   288→        while (self.pos < self.source.len and isIdentifierContinue(self.source[self.pos])) {
   289→            self.pos += 1;
   290→            self.column += 1;
   291→        }
   292→
   293→        const text = self.source[start..self.pos];
   294→        const tag = getKeywordTag(text) orelse .identifier;
   295→
   296→        return Token{
   297→            .tag = tag,
   298→            .loc = .{ .line = self.line, .column = start_column, .start = start, .end = self.pos },
   299→        };
   300→    }
   301→
   302→    fn scanOperator(self: *Tokenizer, start: usize, start_column: usize) Token {
   303→        const c = self.source[self.pos];
   304→        self.pos += 1;
   305→        self.column += 1;
   306→
   307→        const tag: Token.Tag = switch (c) {
   308→            '+' => .plus,
   309→            '-' => {
   310→                if (self.pos < self.source.len and self.source[self.pos] == '>') {
   311→                    self.pos += 1;
   312→                    self.column += 1;
   313→                    return Token{ .tag = .arrow, .loc = .{ .line = self.line, .column = start_column, .start = start, .end = self.pos } };
   314→                }
   315→                return Token{ .tag = .minus, .loc = .{ .line = self.line, .column = start_column, .start = start, .end = self.pos } };
   316→            },
   317→            '*' => .star,
   318→            '/' => .slash,
   319→            '%' => .percent,
   320→            '=' => {
   321→                if (self.pos < self.source.len and self.source[self.pos] == '=') {
   322→                    self.pos += 1;
   323→                    self.column += 1;
   324→                    return Token{ .tag = .equal_equal, .loc = .{ .line = self.line, .column = start_column, .start = start, .end = self.pos } };
   325→                }
   326→                return Token{ .tag = .equal, .loc = .{ .line = self.line, .column = start_column, .start = start, .end = self.pos } };
   327→            },
   328→            '!' => {
   329→                if (self.pos < self.source.len and self.source[self.pos] == '=') {
   330→                    self.pos += 1;
   331→                    self.column += 1;
   332→                    return Token{ .tag = .bang_equal, .loc = .{ .line = self.line, .column = start_column, .start = start, .end = self.pos } };
   333→                }
   334→                return Token{ .tag = .bang, .loc = .{ .line = self.line, .column = start_column, .start = start, .end = self.pos } };
   335→            },
   336→            '<' => {
   337→                if (self.pos < self.source.len) {
   338→                    if (self.source[self.pos] == '=') {
   339→                        self.pos += 1;
   340→                        self.column += 1;
   341→                        return Token{ .tag = .less_equal, .loc = .{ .line = self.line, .column = start_column, .start = start, .end = self.pos } };
   342→                    } else if (self.source[self.pos] == '<') {
   343→                        self.pos += 1;
   344→                        self.column += 1;
   345→                        return Token{ .tag = .lshift, .loc = .{ .line = self.line, .column = start_column, .start = start, .end = self.pos } };
   346→                    }
   347→                }
   348→                return Token{ .tag = .less, .loc = .{ .line = self.line, .column = start_column, .start = start, .end = self.pos } };
   349→            },
   350→            '>' => {
   351→                if (self.pos < self.source.len) {
   352→                    if (self.source[self.pos] == '=') {
   353→                        self.pos += 1;
   354→                        self.column += 1;
   355→                        return Token{ .tag = .greater_equal, .loc = .{ .line = self.line, .column = start_column, .start = start, .end = self.pos } };
   356→                    } else if (self.source[self.pos] == '>') {
   357→                        self.pos += 1;
   358→                        self.column += 1;
   359→                        return Token{ .tag = .rshift, .loc = .{ .line = self.line, .column = start_column, .start = start, .end = self.pos } };
   360→                    }
   361→                }
   362→                return Token{ .tag = .greater, .loc = .{ .line = self.line, .column = start_column, .start = start, .end = self.pos } };
   363→            },
   364→            '&' => .ampersand,
   365→            '|' => .pipe,
   366→            '^' => .caret,
   367→            '~' => .tilde,
   368→            '.' => {
   369→                if (self.pos < self.source.len and self.source[self.pos] == '.') {
   370→                    self.pos += 1;
   371→                    self.column += 1;
   372→                    return Token{ .tag = .dot_dot, .loc = .{ .line = self.line, .column = start_column, .start = start, .end = self.pos } };
   373→                }
   374→                return Token{ .tag = .dot, .loc = .{ .line = self.line, .column = start_column, .start = start, .end = self.pos } };
   375→            },
   376→            '?' => .question,
   377→            ':' => {
   378→                if (self.pos < self.source.len and self.source[self.pos] == ':') {
   379→                    self.pos += 1;
   380→                    self.column += 1;
   381→                    return Token{ .tag = .double_colon, .loc = .{ .line = self.line, .column = start_column, .start = start, .end = self.pos } };
   382→                }
   383→                return Token{ .tag = .colon, .loc = .{ .line = self.line, .column = start_column, .start = start, .end = self.pos } };
   384→            },
   385→            '(' => .lparen,
   386→            ')' => .rparen,
   387→            '{' => .lbrace,
   388→            '}' => .rbrace,
   389→            '[' => .lbracket,
   390→            ']' => .rbracket,
   391→            ';' => .semicolon,
   392→            ',' => .comma,
   393→            else => .invalid,
   394→        };
   395→
   396→        return Token{
   397→            .tag = tag,
   398→            .loc = .{ .line = self.line, .column = start_column, .start = start, .end = self.pos },
   399→        };
   400→    }
   401→
   402→    fn peek(self: *Tokenizer) u8 {
   403→        if (self.pos + 1 >= self.source.len) return 0;
   404→        return self.source[self.pos + 1];
   405→    }
   406→};
   407→
   408→fn isWhitespace(c: u8) bool {
   409→    return c == ' ' or c == '\t' or c == '\n' or c == '\r';
   410→}
   411→
   412→fn isDigit(c: u8) bool {
   413→    return c >= '0' and c <= '9';
   414→}
   415→
   416→fn isAlpha(c: u8) bool {
   417→    return (c >= 'a' and c <= 'z') or (c >= 'A' and c <= 'Z') or c == '_';
   418→}
   419→
   420→fn isIdentifierStart(c: u8) bool {
   421→    return isAlpha(c);
   422→}
   423→
   424→fn isIdentifierContinue(c: u8) bool {
   425→    return isAlpha(c) or isDigit(c);
   426→}
   427→
   428→fn getKeywordTag(text: []const u8) ?Token.Tag {
   429→    return switch (std.meta.stringToEnum(Token.Tag, text ++ "_") orelse return null) {
   430→        inline .fn_, .const_, .var_, .if_, .else_, .while_, .for_, .return_, .struct_, .enum_, .union_, .error_, .try_, .catch_, .pub_, .inline_, .comptime_, .true_, .false_, .null_, .and_, .or_, .not_ => |tag| tag,
   431→        else => null,
   432→    };
   433→}
   434→
   435→// Test
   436→pub fn main() !void {
   437→    var gpa = std.heap.GeneralPurposeAllocator(.{}){};
   438→    defer _ = gpa.deinit();
   439→    const allocator = gpa.allocator();
   440→
   441→    const source = "fn add(a: i32, b: i32) -> i32 { return a + b; }";
   442→
   443→    var tokenizer = Tokenizer.init(source);
   444→    var tokens = std.ArrayList(Token).init(allocator);
   445→    defer tokens.deinit();
   446→
   447→    while (true) {
   448→        const token = tokenizer.nextToken();
   449→        try tokens.append(token);
   450→        std.debug.print("Token: {s:15} = \"{s}\"\n", .{ @tagName(token.tag), token.lexeme(source) });
   451→
   452→        if (token.tag == .eof) break;
   453→    }
   454→}
