     1→// 🦎 Mini Zig Compiler - Main Entry Point
     2→// src/main.zig: Tokenizer → Parser → AST → AstGen → ZIR → Sema → AIR → Codegen → Linker
     3→
     4→const std = @import("std");
     5→const Tokenizer = @import("tokenizer.zig").Tokenizer;
     6→const Token = @import("tokenizer.zig").Token;
     7→const Parser = @import("parser.zig").Parser;
     8→const Ast = @import("ast.zig");
     9→const printAst = @import("ast.zig").printAst;
    10→const AstGen = @import("astgen.zig").AstGen;
    11→const printZir = @import("zir.zig").printZir;
    12→const Sema = @import("sema.zig").Sema;
    13→const printAir = @import("air.zig").printAir;
    14→const Codegen = @import("codegen.zig").Codegen;
    15→const Linker = @import("linker.zig").Linker;
    16→
    17→pub fn main() !void {
    18→    var gpa = std.heap.GeneralPurposeAllocator(.{}){};
    19→    defer _ = gpa.deinit();
    20→    const allocator = gpa.allocator();
    21→
    22→    // CLI 인수 처리
    23→    const args = try std.process.argsAlloc(allocator);
    24→    defer std.process.argsFree(allocator, args);
    25→
    26→    var emit_c_only = false;
    27→    var input_file: ?[]const u8 = null;
    28→    var output_file: []const u8 = "output";
    29→
    30→    // 인수 파싱
    31→    var i: usize = 1;
    32→    while (i < args.len) : (i += 1) {
    33→        if (std.mem.eql(u8, args[i], "--emit-c")) {
    34→            emit_c_only = true;
    35→        } else if (std.mem.eql(u8, args[i], "-o")) {
    36→            i += 1;
    37→            if (i < args.len) {
    38→                output_file = args[i];
    39→            }
    40→        } else if (!std.mem.startsWith(u8, args[i], "-")) {
    41→            input_file = args[i];
    42→        }
    43→    }
    44→
    45→    // 입력 파일이 없으면 테스트 코드 사용
    46→    const source = if (input_file) |file| blk: {
    47→        const file_handle = try std.fs.cwd().openFile(file, .{});
    48→        defer file_handle.close();
    49→        const file_size = try file_handle.getEndPos();
    50→        const buffer = try allocator.alloc(u8, file_size);
    51→        const bytes_read = try file_handle.readAll(buffer);
    52→        if (bytes_read != file_size) {
    53→            return error.IncompleteRead;
    54→        }
    55→        break :blk buffer;
    56→    } else blk: {
    57→        // 테스트 소스 코드
    58→        const test_source =
    59→            \\fn add(a: i32, b: i32) i32 {
    60→            \\    return a + b;
    61→            \\}
    62→            \\
    63→            \\fn main() i32 {
    64→            \\    const x = add(1, 2);
    65→            \\    const y = x + 3;
    66→            \\    return y;
    67→            \\}
    68→        ;
    69→        break :blk test_source;
    70→    };
    71→    defer if (input_file != null) allocator.free(source);
    72→
    73→    std.debug.print("========== Mini Zig Compiler (Phase 2.7) ==========\n\n", .{});
    74→
    75→    // Step 1: Tokenize
    76→    std.debug.print("[Step 1] TOKENIZE\n", .{});
    77→    std.debug.print("─────────────────────────\n", .{});
    78→
    79→    var tokenizer = try Tokenizer.init(source, allocator);
    80→    defer tokenizer.deinit();
    81→
    82→    var tokens = std.ArrayList(Token).init(allocator);
    83→    defer tokens.deinit();
    84→
    85→    while (try tokenizer.nextToken()) |token| {
    86→        try tokens.append(token);
    87→    }
    88→
    89→    std.debug.print("✅ Tokenized {} tokens\n\n", .{tokens.items.len});
    90→
    91→    // Step 2: Parse
    92→    std.debug.print("[Step 2] PARSE\n", .{});
    93→    std.debug.print("─────────────────────────\n", .{});
    94→
    95→    var parser = try Parser.init(tokens.items, source, allocator);
    96→    defer parser.deinit();
    97→    const ast = try parser.parseProgram();
    98→
    99→    std.debug.print("✅ Parsed successfully\n\n", .{});
   100→
   101→    // Step 3: AstGen (AST → ZIR)
   102→    std.debug.print("[Step 3] ASTGEN (AST → ZIR)\n", .{});
   103→    std.debug.print("─────────────────────────\n", .{});
   104→
   105→    var astgen = try AstGen.init(allocator, source);
   106→    defer astgen.deinit();
   107→    try astgen.genProgram(&ast);
   108→
   109→    std.debug.print("✅ Generated ZIR with {} instructions\n\n", .{astgen.zir.instructions.items.len});
   110→
   111→    // Step 4: Sema (ZIR → AIR with Type Information)
   112→    std.debug.print("[Step 4] SEMA (ZIR → AIR)\n", .{});
   113→    std.debug.print("─────────────────────────\n", .{});
   114→
   115→    var sema = try Sema.init(allocator, &astgen.zir);
   116→    defer sema.deinit();
   117→    try sema.analyzeProgram();
   118→
   119→    if (sema.hasErrors()) {
   120→        std.debug.print("\n⚠️  Semantic errors found:\n", .{});
   121→        sema.printErrors();
   122→        return;
   123→    }
   124→
   125→    std.debug.print("✅ Semantic analysis complete, {} AIR instructions\n\n", .{sema.air.instructions.items.len});
   126→
   127→    // Step 5: Codegen (AIR → C Code)
   128→    std.debug.print("[Step 5] CODEGEN (AIR → C)\n", .{});
   129→    std.debug.print("─────────────────────────\n", .{});
   130→
   131→    var codegen = try Codegen.init(allocator, &sema.air);
   132→    defer codegen.deinit();
   133→
   134→    const c_code = try codegen.generate();
   135→    const c_filename = try std.fmt.allocPrint(allocator, "{s}.c", .{output_file});
   136→    defer allocator.free(c_filename);
   137→
   138→    try codegen.generateToFile(c_filename);
   139→    std.debug.print("✅ Generated C code: {} bytes written to {s}\n\n", .{ c_code.len, c_filename });
   140→
   141→    // --emit-c 플래그가 있으면 여기서 종료
   142→    if (emit_c_only) {
   143→        std.debug.print("[Summary] C code generation complete\n", .{});
   144→        std.debug.print("C file: {s}\n", .{c_filename});
   145→        return;
   146→    }
   147→
   148→    // Step 6: Linker (C → Binary)
   149→    std.debug.print("[Step 6] LINKER (C → Binary)\n", .{});
   150→    std.debug.print("─────────────────────────\n", .{});
   151→
   152→    var linker = try Linker.init(allocator);
   153→    defer linker.deinit();
   154→
   155→    const binary_filename = output_file;
   156→    linker.compile(c_filename, binary_filename) catch |err| {
   157→        std.debug.print("❌ Compilation failed: {}\n", .{err});
   158→        // C 파일은 유지하고 에러만 출력
   159→        std.debug.print("💾 C source retained: {s}\n", .{c_filename});
   160→        return;
   161→    };
   162→
   163→    std.debug.print("✅ Compiled to binary: {s}\n\n", .{binary_filename});
   164→
   165→    // 정리 및 요약
   166→    std.debug.print("========== Compilation Complete ==========\n", .{});
   167→    std.debug.print("📊 Summary:\n", .{});
   168→    std.debug.print("  Tokens:       {}\n", .{tokens.items.len});
   169→    std.debug.print("  ZIR Inst:     {}\n", .{astgen.zir.instructions.items.len});
   170→    std.debug.print("  AIR Inst:     {}\n", .{sema.air.instructions.items.len});
   171→    std.debug.print("  C Code Size:  {} bytes\n", .{c_code.len});
   172→    std.debug.print("  Output:       {s}\n", .{binary_filename});
   173→    std.debug.print("  C Source:     {s}\n", .{c_filename});
   174→}
