   190→                stdout.print("load_int {}\n", .{data.value}) catch {};
   191→            },
   192→            .load_float => |data| {
   193→                stdout.print("load_float {}\n", .{data.value}) catch {};
   194→            },
   195→            .load_string => |data| {
   196→                stdout.print("load_string @{}\n", .{data.index}) catch {};
   197→            },
   198→            .load_var => |data| {
   199→                stdout.print("load_var @{}\n", .{data.name_index}) catch {};
   200→            },
   201→            .store_var => |data| {
   202→                stdout.print("store_var @{} = %{}\n", .{ data.name_index, data.value }) catch {};
   203→            },
   204→            .binary_op => |data| {
   205→                stdout.print("binary_op {:s} %{} %{}\n", .{ @tagName(data.op), data.lhs, data.rhs }) catch {};
   206→            },
   207→            .unary_op => |data| {
   208→                stdout.print("unary_op {:s} %{}\n", .{ @tagName(data.op), data.operand }) catch {};
   209→            },
   210→            .fn_begin => |data| {
   211→                stdout.print("fn_begin @{} (params: {})\n", .{ data.name_index, data.params.len }) catch {};
   212→            },
   213→            .generic_fn_begin => |data| {
   214→                stdout.print("generic_fn_begin @{} (comptime: {}, total: {})\n", .{ data.name_index, data.comptime_param_count, data.params.len }) catch {};
   215→            },
   216→            .union_begin => |data| {
   217→                stdout.print("union_begin @{} (fields: {}, tagged: {})\n", .{ data.name_index, data.field_count, data.is_tagged }) catch {};
   218→            },
   219→            .union_field => |data| {
   220→                stdout.print("union_field @{} type:%{}\n", .{ data.field_name_index, data.field_type }) catch {};
   221→            },
   222→            .enum_begin => |data| {
   223→                stdout.print("enum_begin @{} (values: {}, tagged: {})\n", .{ data.name_index, data.value_count, data.is_tagged }) catch {};
   224→            },
   225→            .enum_value => |data| {
   226→                if (data.value) |v| {
   227→                    stdout.print("enum_value @{} value:%{}\n", .{ data.value_name_index, v }) catch {};
   228→                } else {
   229→                    stdout.print("enum_value @{}\n", .{data.value_name_index}) catch {};
   230→                }
   231→            },
   232→
   233→            // Comptime Programming (Phase 3.3)
   234→            .comptime_begin => |data| {
   235→                stdout.print("comptime_begin (body: %{} - %{})\n", .{ data.body_start, data.body_end }) catch {};
   236→            },
   237→            .const_expr => |data| {
   238→                if (data.type_index) |type_idx| {
   239→                    stdout.print("const_expr @{} type:@{} value:%{}\n", .{ data.name_index, type_idx, data.value }) catch {};
   240→                } else {
   241→                    stdout.print("const_expr @{} value:%{}\n", .{ data.name_index, data.value }) catch {};
   242→                }
   243→            },
   244→            .eval_at_comptime => |data| {
