   262→                    stdout.print("return void\n", .{}) catch {};
   263→                }
   264→            },
   265→            .block_begin => |data| {
   266→                stdout.print("block_begin @{}\n", .{data.label}) catch {};
   267→            },
   268→            .block_end => {
   269→                stdout.print("block_end\n", .{}) catch {};
   270→            },
   271→            .array_literal => |data| {
   272→                stdout.print("array_literal (elements: {})\n", .{data.elements.len}) catch {};
   273→            },
   274→            .noop => {
   275→                stdout.print("noop\n", .{}) catch {};
   276→            },
   277→            else => {
   278→                stdout.print("{s}\n", .{@tagName(inst)}) catch {};
   279→            },
   280→        }
   281→    }
   282→
   283→    stdout.print("{s}=== Strings ===\n", .{spaces}) catch {};
   284→    var iter = zir.strings.iterator();
   285→    var idx: u32 = 0;
   286→    while (iter.next()) |entry| {
   287→        stdout.print("{s}@{}: \"{s}\"\n", .{ spaces, idx, entry.value_ptr.* }) catch {};
   288→        idx += 1;
   289→    }
   290→}
