     1→// 🦎 Mini Zig Compiler - Phase 2.3: AstGen
     2→// src/astgen.zig: AST → ZIR (Untyped Intermediate Representation)
     3→
     4→const std = @import("std");
     5→const Ast = @import("ast.zig");
     6→const Node = Ast.Node;
     7→const Zir = @import("zir.zig").Zir;
     8→
     9→pub const AstGen = struct {
    10→    zir: *Zir,
    11→    allocator: std.mem.Allocator,
    12→    source: []const u8,
    13→    function_decls: std.StringHashMap(std.ArrayList(*const Node)),
    14→
    15→    pub fn init(allocator: std.mem.Allocator, source: []const u8) !AstGen {
    16→        var zir = try allocator.create(Zir);
    17→        zir.* = Zir.init(allocator);
    18→
    19→        return .{
    20→            .zir = zir,
    21→            .allocator = allocator,
    22→            .source = source,
    23→            .function_decls = std.StringHashMap(std.ArrayList(*const Node)).init(allocator),
    24→        };
    25→    }
    26→
    27→    pub fn deinit(self: *AstGen) void {
    28→        self.zir.deinit();
    29→        self.allocator.destroy(self.zir);
    30→        var iter = self.function_decls.iterator();
    31→        while (iter.next()) |entry| {
    32→            entry.value_ptr.deinit();
    33→        }
    34→        self.function_decls.deinit();
    35→    }
    36→
    37→    /// 전체 프로그램 생성
    38→    pub fn genProgram(self: *AstGen, ast: *const Ast) !void {
    39→        // root 노드의 블록 생성
    40→        if (ast.root.data == .block) {
    41→            // 첫 번째 pass: 모든 함수 선언 수집 (오버로드 감지)
    42→            for (ast.root.data.block) |stmt| {
    43→                if (stmt.tag == .fn_decl) {
    44→                    const fn_name = stmt.data.fn_decl.name;
    45→                    var entry = try self.function_decls.getOrPut(fn_name);
    46→                    if (entry.value_ptr.* == undefined) {
    47→                        entry.value_ptr.* = std.ArrayList(*const Node).init(self.allocator);
    48→                    }
    49→                    try entry.value_ptr.append(&stmt);
    50→                }
    51→            }
    52→
    53→            // 두 번째 pass: ZIR 생성
    54→            var processed_fn_names = std.StringHashMap(bool).init(self.allocator);
    55→            defer processed_fn_names.deinit();
    56→
    57→            for (ast.root.data.block) |stmt| {
    58→                if (stmt.tag == .fn_decl) {
    59→                    const fn_name = stmt.data.fn_decl.name;
    60→                    // 이미 처리한 오버로드 그룹은 건너뛰기
    61→                    if (processed_fn_names.contains(fn_name)) {
    62→                        continue;
    63→                    }
    64→
    65→                    const decls = self.function_decls.get(fn_name).?;
    66→                    if (decls.items.len > 1) {
    67→                        // 오버로드 그룹: 모든 오버로드 버전 처리
    68→                        _ = try self.genOverloadGroup(fn_name, decls.items);
    69→                    } else {
    70→                        // 일반 함수: 단일 버전
    71→                        _ = try self.genNode(&stmt);
    72→                    }
    73→                    try processed_fn_names.put(fn_name, true);
    74→                } else {
    75→                    _ = try self.genNode(&stmt);
    76→                }
    77→            }
    78→        }
    79→    }
    80→

