     6→
     7→/// C 코드 생성기 (AIR → C 코드)
     8→pub const Codegen = struct {
     9→    air: *const Air,
    10→    allocator: std.mem.Allocator,
    11→    output: std.ArrayList(u8),
    12→    indent_level: usize,
    13→    temp_counter: u32,
    14→    ref_to_temp: std.AutoHashMap(Ref, []const u8),
    15→
    16→    pub fn init(allocator: std.mem.Allocator, air: *const Air) !Codegen {
    17→        return Codegen{
    18→            .air = air,
    19→            .allocator = allocator,
    20→            .output = std.ArrayList(u8).init(allocator),
    21→            .indent_level = 0,
    22→            .temp_counter = 0,
    23→            .ref_to_temp = std.AutoHashMap(Ref, []const u8).init(allocator),
    24→        };
    25→    }
    26→
    27→    pub fn deinit(self: *Codegen) void {
    28→        self.output.deinit();
    29→        self.ref_to_temp.deinit();
    30→    }
    31→
    32→    /// AIR 프로그램을 C 코드로 생성
    33→    pub fn generate(self: *Codegen) ![]const u8 {
    34→        try self.emitHeaders();
    35→        try self.emitDeclarations();
    36→        return self.output.items;
    37→    }
    38→
    39→    /// 생성된 C 코드를 파일로 저장
    40→    pub fn generateToFile(self: *Codegen, path: []const u8) !void {
    41→        const c_code = try self.generate();
    42→        const file = try std.fs.cwd().createFile(path, .{});
    43→        defer file.close();
    44→        try file.writeAll(c_code);
    45→    }
    46→
    47→    // ========== 헤더 & 기본 구조 ==========
    48→
    49→    fn emitHeaders(self: *Codegen) !void {
    50→        try self.output.appendSlice("#include <stdio.h>\n");
    51→        try self.output.appendSlice("#include <string.h>\n");
    52→        try self.output.appendSlice("#include <stdlib.h>\n\n");
    53→    }
    54→
    55→    fn emitDeclarations(self: *Codegen) !void {
    56→        for (self.air.instructions.items, 0..) |inst, idx| {
    57→            const ref: Ref = @intCast(idx);
    58→            try self.emitInstruction(inst, ref);
    59→        }
    60→    }
    61→
    62→    // ========== 타입 변환 ==========
    63→
    64→    fn typeToCString(self: *Codegen, ty: AirType) ![]const u8 {
    65→        _ = self;
    66→        return switch (ty) {
    67→            .void => "void",
    68→            .i32 => "int",
    69→            .i64 => "long long",
    70→            .f32 => "float",
    71→            .f64 => "double",
    72→            .bool => "int",
    73→            .string => "const char*",
    74→            .array => "array", // TODO: 배열 타입 처리
    75→            .function => "function", // TODO: 함수 포인터
    76→            .unknown => "int", // 기본값
    77→        };
    78→    }
    79→
